import{_ as e}from"./chunks/prontera-street.BZRjh5Zm.js";import{_ as r,o as t,c as o,ag as i}from"./chunks/framework.DGzMGr_a.js";const b=JSON.parse('{"title":"法师毕业配装推荐（平民/氪金两套方案）","description":"RO3 法师各阶段配装，零氪到毕业全套方案","frontmatter":{"title":"法师毕业配装推荐（平民/氪金两套方案）","description":"RO3 法师各阶段配装，零氪到毕业全套方案"},"headers":[],"relativePath":"jobs/mage-equip.md","filePath":"jobs/mage-equip.md","lastUpdated":1780230058000}'),l={name:"jobs/mage-equip.md"};function n(h,a,s,d,p,c){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="法师毕业配装推荐" tabindex="-1">法师毕业配装推荐 <a class="header-anchor" href="#法师毕业配装推荐" aria-label="Permalink to &quot;法师毕业配装推荐&quot;">​</a></h1><p><img src="'+e+'" alt="RO3 法师配装"></p><p>适用版本：v1.0.2</p><p>法师群攻能力最强、升级最快，配装核心：<strong>优先堆魔法攻击、魔法穿透，其次堆蓝量和冷却缩减</strong>。</p><h2 id="平民零氪配装-总造价-10万z" tabindex="-1">平民零氪配装（总造价 &lt; 10万z） <a class="header-anchor" href="#平民零氪配装-总造价-10万z" aria-label="Permalink to &quot;平民零氪配装（总造价 &lt; 10万z）&quot;">​</a></h2><p>适合零氪/新手，装备均可通过刷怪、任务、商店购买获得。</p><h3 id="武器-4-魔法杖-任务奖励" tabindex="-1">武器：+4 魔法杖（任务奖励） <a class="header-anchor" href="#武器-4-魔法杖-任务奖励" aria-label="Permalink to &quot;武器：+4 魔法杖（任务奖励）&quot;">​</a></h3><p>主线任务 20 级奖励，魔法攻击 +85，足够用到 50 级。</p><h3 id="头部-3-魔法帽-商店购买" tabindex="-1">头部：+3 魔法帽（商店购买） <a class="header-anchor" href="#头部-3-魔法帽-商店购买" aria-label="Permalink to &quot;头部：+3 魔法帽（商店购买）&quot;">​</a></h3><p>普隆德拉道具店购买，魔法攻击 +12，魔法防御 +8。</p><h3 id="衣服-3-魔法长袍-古城副本掉落" tabindex="-1">衣服：+3 魔法长袍（古城副本掉落） <a class="header-anchor" href="#衣服-3-魔法长袍-古城副本掉落" aria-label="Permalink to &quot;衣服：+3 魔法长袍（古城副本掉落）&quot;">​</a></h3><p>古城副本普通难度掉落，魔法攻击 +15，蓝量 +100。</p><h3 id="饰品-魔法戒指-×2-蚂蚁洞掉落" tabindex="-1">饰品：魔法戒指 ×2（蚂蚁洞掉落） <a class="header-anchor" href="#饰品-魔法戒指-×2-蚂蚁洞掉落" aria-label="Permalink to &quot;饰品：魔法戒指 ×2（蚂蚁洞掉落）&quot;">​</a></h3><p>蚂蚁洞刷蚂蚁卵掉落，每个魔法攻击 +8。</p><h3 id="卡片搭配-波利卡-×2-绿棉虫卡-×2" tabindex="-1">卡片搭配：波利卡 ×2 + 绿棉虫卡 ×2 <a class="header-anchor" href="#卡片搭配-波利卡-×2-绿棉虫卡-×2" aria-label="Permalink to &quot;卡片搭配：波利卡 ×2 + 绿棉虫卡 ×2&quot;">​</a></h3><p>波利卡（武器/头部）：魔法攻击 +5；绿棉虫卡（衣服/饰品）：蓝量 +50。</p><p><strong>属性加点</strong>：INT 满 → DEX 30 → VIT 20 → 剩余 AGI</p><h2 id="氪金毕业配装-总造价-≈-500元" tabindex="-1">氪金毕业配装（总造价 ≈ 500元） <a class="header-anchor" href="#氪金毕业配装-总造价-≈-500元" aria-label="Permalink to &quot;氪金毕业配装（总造价 ≈ 500元）&quot;">​</a></h2><p>适合微氪/氪金玩家，追求极限输出。</p><h3 id="武器-10-红莲魔法杖-💰" tabindex="-1">武器：+10 红莲魔法杖 💰 <a class="header-anchor" href="#武器-10-红莲魔法杖-💰" aria-label="Permalink to &quot;武器：+10 红莲魔法杖 💰&quot;">​</a></h3><p>魔法攻击 +220，火属性魔法伤害 +15%。</p><h3 id="头部-10-智慧头冠-💰" tabindex="-1">头部：+10 智慧头冠 💰 <a class="header-anchor" href="#头部-10-智慧头冠-💰" aria-label="Permalink to &quot;头部：+10 智慧头冠 💰&quot;">​</a></h3><p>魔法攻击 +35，INT +10，冷却缩减 +5%。</p><h3 id="衣服-10-神秘法袍-💰" tabindex="-1">衣服：+10 神秘法袍 💰 <a class="header-anchor" href="#衣服-10-神秘法袍-💰" aria-label="Permalink to &quot;衣服：+10 神秘法袍 💰&quot;">​</a></h3><p>魔法攻击 +40，魔法防御 +30，受击 10% 概率触发「魔法盾」。</p><h3 id="饰品-魔力手镯-×2-冷却戒指-×2-💰" tabindex="-1">饰品：魔力手镯 ×2 + 冷却戒指 ×2 💰 <a class="header-anchor" href="#饰品-魔力手镯-×2-冷却戒指-×2-💰" aria-label="Permalink to &quot;饰品：魔力手镯 ×2 + 冷却戒指 ×2 💰&quot;">​</a></h3><p>魔力手镯魔法攻击 +25/个，冷却戒指冷却缩减 +8%/个。</p><h3 id="卡片搭配-邪派浪人卡-×4-金属波利卡-×2-💰" tabindex="-1">卡片搭配：邪派浪人卡 ×4 + 金属波利卡 ×2 💰 <a class="header-anchor" href="#卡片搭配-邪派浪人卡-×4-金属波利卡-×2-💰" aria-label="Permalink to &quot;卡片搭配：邪派浪人卡 ×4 + 金属波利卡 ×2 💰&quot;">​</a></h3><p>邪派浪人卡：魔法穿透 +10/个；金属波利卡：魔法攻击 +15/个。</p><p><strong>属性加点</strong>：INT 满 → DEX 50 → 剩余全 AGI</p><h2 id="各阶段过渡建议" tabindex="-1">各阶段过渡建议 <a class="header-anchor" href="#各阶段过渡建议" aria-label="Permalink to &quot;各阶段过渡建议&quot;">​</a></h2><ul><li><strong>1-30 级</strong>：任务送的魔法杖 + 商店基础装备</li><li><strong>30-60 级</strong>：古城副本衣服 + 蚂蚁洞饰品</li><li><strong>60-99 级</strong>：攒钱买红莲魔法杖，逐步替换氪金装备</li><li><strong>毕业</strong>：全套 +10 氪金装备 + 邪派浪人卡，魔法攻击突破 800</li></ul>',32)])])}const m=r(l,[["render",n]]);export{b as __pageData,m as default};
